import{_ as e,o as a,c as r,a0 as d}from"./chunks/framework.DzvPB4Y-.js";const f=JSON.parse('{"title":"二维套裁 CSP2D","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/frameworks/csp2d/index.md","filePath":"zh-cn/frameworks/csp2d/index.md"}'),o={name:"zh-cn/frameworks/csp2d/index.md"};function l(i,t,n,h,c,s){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="二维套裁-csp2d" tabindex="-1">二维套裁 CSP2D <a class="header-anchor" href="#二维套裁-csp2d" aria-label="Permalink to &quot;二维套裁 CSP2D&quot;">​</a></h1><p>把定尺板材或卷材裁成矩形产品，同时满足订单和设备工艺。第一课先学定尺板与 Freeform，再比较卷材、两级和三级断头台工艺。</p><h2 id="最少需要理解的对象" tabindex="-1">最少需要理解的对象 <a class="header-anchor" href="#最少需要理解的对象" aria-label="Permalink to &quot;最少需要理解的对象&quot;">​</a></h2><table tabindex="0"><thead><tr><th>业务概念</th><th>API</th><th>输入或输出</th></tr></thead><tbody><tr><td>供料</td><td><code>Material2</code></td><td>固定宽高为板材，无固定高度为卷材</td></tr><tr><td>产品与需求</td><td><code>Product2</code> / <code>ProductDemand2</code></td><td>尺寸、件数等需求模式</td></tr><tr><td>图案</td><td><code>Pattern2</code></td><td>坐标、覆盖贡献与可选切分树</td></tr><tr><td>方案</td><td><code>CuttingPlan2</code></td><td>原料消耗与图案使用</td></tr><tr><td>问题</td><td><code>Csp2dProblem</code></td><td>物料、产品、需求、刀缝、工艺和配置</td></tr></tbody></table><p>Freeform 要求几何合法；两级/三级断头台还需要合法切分树。板材的张数和卷材的消耗长度是不同目标口径。</p><h2 id="从哪个入口调用" tabindex="-1">从哪个入口调用？ <a class="header-anchor" href="#从哪个入口调用" aria-label="Permalink to &quot;从哪个入口调用？&quot;">​</a></h2><p>Kotlin 使用 <code>Csp2dMilp</code> / <code>Csp2dColumnGeneration</code>。Rust 使用 <code>Csp2dSolvers</code>，默认带内置启发式，可注入 <code>Csp2dMasterSolver</code>。接口名称带 MILP，不代表未注入后端的 Rust 默认路径真的调用了原生 MILP。</p><p>两种语言的当前实现与配置并不完全对称；从各自可执行用例出发，不把对照代码误当作能力一致性承诺。</p><h2 id="能力边界" tabindex="-1">能力边界 <a class="header-anchor" href="#能力边界" aria-label="Permalink to &quot;能力边界&quot;">​</a></h2><ul><li>当前面向矩形产品，不是任意多边形异形套料。</li><li>坐标合法不等于工艺合法，断头台方案需要通过切分树校验。</li><li>残余需求驱动或估计价格筛选不构成真实 LP 对偶定价证书。</li><li>默认启发式得到覆盖方案，不等于完整问题已证明最优。</li></ul><h2 id="学习路线" tabindex="-1">学习路线 <a class="header-anchor" href="#学习路线" aria-label="Permalink to &quot;学习路线&quot;">​</a></h2><ol><li>完成<a href="./../setup.html">环境准备</a>。</li><li>跟随<a href="./first-cutting.html">第一次板材套裁</a>，从产品件数与方案使用量开始。</li><li>增加刀缝，再切换卷材或断头台工艺，分别检查消耗与可制造性。</li><li>如果只需要已有物品的几何装载，比较 <a href="./../bpp2d/">BPP2D</a>。</li></ol><h2 id="接口参考" tabindex="-1">接口参考 <a class="header-anchor" href="#接口参考" aria-label="Permalink to &quot;接口参考&quot;">​</a></h2><ul><li><a href="https://github.com/fuookami/ospf-kotlin/blob/main/ospf-kotlin-framework-csp2d/README_ch.md" target="_blank" rel="noreferrer">Kotlin 模块与工艺说明</a></li><li><a href="https://github.com/fuookami/ospf-rust/blob/main/ospf-rust-framework-csp2d/README_ch.md" target="_blank" rel="noreferrer">Rust API、主问题与定价边界</a></li></ul><p>Kotlin 模块 README 的历史阶段描述可能落后于应用源码；本教程展示当前公开 API 的业务示例，源码契约另见验证参考，不以阶段标签推断能力。</p><p><a href="./../">返回场景选型</a></p><h2 id="继续实践" tabindex="-1">继续实践 <a class="header-anchor" href="#继续实践" aria-label="Permalink to &quot;继续实践&quot;">​</a></h2><p>下一课：<a href="./business-scenario.html">刀缝、工艺与卷材</a>。将场景迁入自己的应用前，完成<a href="./../integration.html">业务接入检查</a>。</p>',18)])])}const u=e(o,[["render",l]]);export{f as __pageData,u as default};
